import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info"); // success | error | info

  // Démarrer la caméra au chargement
  useEffect(() => {
    const startCamera = async () => {
      try {
        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
      } catch (err) {
        setMessage("❌ Impossible d'accéder à la caméra. Vérifiez les permissions.");
        setMessageType("error");
        console.error(err);
      }
    };

    startCamera();

    // Nettoyage quand on quitte le composant
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleCapture = useCallback(async () => {
    if (!videoRef.current) return;

    setLoading(true);
    setMessage("⏳ Capture et analyse en cours...");
    setMessageType("info");

    try {
      // Créer un canvas pour capturer l'image
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);

      const imageSrc = canvas.toDataURL('image/jpeg', 0.95);

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 RAW RESPONSE:", response);
      console.log("📊 DATA:", data);

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setMessage(`✅ ${name} - Confiance : ${confidence}%`);
        setMessageType("success");
      } else {
        setMessage(String(data.message || data.error || "Visage non reconnu"));
        setMessageType("error");
      }
    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message || "Erreur serveur";
      setMessage(`❌ ${String(errorMsg)}`);
      setMessageType("error");
      console.error("Erreur reconnaissance :", err);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000', 
        marginBottom: '30px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.3)'
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
      </div>

      <button 
        onClick={handleCapture}
        disabled={loading}
        style={{
          padding: '16px 40px',
          fontSize: '18px',
          background: loading ? '#6b7280' : '#4F46E5',
          color: 'white',
          border: 'none',
          borderRadius: '10px',
          cursor: loading ? 'not-allowed' : 'pointer',
          fontWeight: '600'
        }}
      >
        {loading ? '⏳ Analyse en cours...' : '🔍 Capturer & Analyser'}
      </button>

      {message && (
        <div style={{
          marginTop: '30px',
          padding: '25px',
          borderRadius: '12px',
          fontSize: '20px',
          fontWeight: '500',
          backgroundColor: messageType === 'success' ? '#DCFCE7' : '#FEE2E2',
          color: messageType === 'success' ? '#166534' : '#991B1B',
          border: `3px solid ${messageType === 'success' ? '#86EFAC' : '#FECACA'}`
        }}>
          {message}
        </div>
      )}

      {!message && !loading && (
        <p style={{ color: '#64748B', marginTop: '20px' }}>
          La caméra devrait s'allumer automatiquement. Cliquez sur le bouton pour analyser.
        </p>
      )}
    </div>
  );
};

export default CameraRecognition;
